for tid, name, region, diff, pts, tf_up, tf_down in NEW_TRAILS:
    if tid in trail_geo:
        print("SKIP (already exists):", tid)
        continue
    if tf_up is None and tf_down is None:
        official = None
    else:
        simp = douglas_peucker(dedupe_points(pts))
        length_km = round(cumulative_km([p[:2] for p in simp])[-1], 2)
        official = (length_km, tf_up, tf_down)
    entry, coords, prof = build_trail(tid, name, region, diff, pts, official=official, elevation=elev)
    line_trails.append(entry)
    trail_geo[tid] = coords
    elevation_profiles[tid] = prof
    print("added", tid, entry["len"], entry["up"], entry["down"])

write_region(REGION_PATH, line_trails, trail_geo, elevation_profiles, data.get("places"))
print("done, total trails:", len(line_trails))
